def max_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    inc = arr[:]
    for i in range(n):
        for j in range(i):
            if arr[j] < arr[i]:
                inc[i] = max(inc[i], inc[j] + arr[i])

    dec = arr[:]
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if arr[j] < arr[i]:
                dec[i] = max(dec[i], dec[j] + arr[i])

    max_sum_val = 0
    for i in range(n):
        max_sum_val = max(max_sum_val, inc[i] + dec[i] - arr[i])

    return max_sum_val
