def is_majority(arr, n, x):
    first = binary_search_first(arr, 0, n - 1, x)
    if first == -1:
        return False

    last = binary_search_last(arr, 0, n - 1, x)

    count = last - first + 1
    return count > n // 2

def binary_search_first(arr, low, high, x):
    if high >= low:
        mid = low + (high - low) // 2
        if (mid == 0 or x > arr[mid - 1]) and arr[mid] == x:
            return mid
        elif x > arr[mid]:
            return binary_search_first(arr, mid + 1, high, x)
        else:
            return binary_search_first(arr, low, mid - 1, x)
    return -1

def binary_search_last(arr, low, high, x):
    if high >= low:
        mid = low + (high - low) // 2
        if (mid == len(arr) - 1 or x < arr[mid + 1]) and arr[mid] == x:
            return mid
        elif x < arr[mid]:
            return binary_search_last(arr, low, mid - 1, x)
        else:
            return binary_search_last(arr, mid + 1, high, x)
    return -1
```

