def eulerian_num(n, m):
    if m < 0 or m >= n:
        return 0
    if n == 0:
        return 1 if m == 0 else 0

    dp = [0] * (m + 1)
    dp[0] = 1

    for i in range(1, n):
        new_dp = [0] * (m + 1)
        for j in range(min(i, m) + 1):
            val = 0
            if j < m:
                val += dp[j] * (i - j)
            if j > 0:
                val += dp[j - 1] * (j + 1)
            new_dp[j] = val
        dp = new_dp

    return dp[m]
