def max_sub_array_sum_repeated(arr, n, k):
    def kadane(arr):
        max_ending_here = max_so_far = arr[0]
        for x in arr[1:]:
            max_ending_here = max(x, max_ending_here + x)
            max_so_far = max(max_so_far, max_ending_here)
        return max_so_far

    total_sum = sum(arr)

    if k == 1:
        return kadane(arr)

    max_prefix = float('-inf')
    curr = 0
    for x in arr:
        curr += x
        max_prefix = max(max_prefix, curr)

    max_suffix = float('-inf')
    curr = 0
    for x in reversed(arr):
        curr += x
        max_suffix = max(max_suffix, curr)

    max_subarray_single = kadane(arr)

    if total_sum > 0:
        return max(max_subarray_single, max_prefix + max_suffix + (k - 2) * total_sum)
    else:
        return max(max_subarray_single, max_prefix + max_suffix)
```

