def set_left_most_unset_bit(n):
    if n == 0:
        return 1

    position = 0
    temp = n
    while temp:
        temp >>= 1
        position += 1

    mask = 1 << position
    while mask:
        if not (n & mask):
            return n | mask
        mask >>= 1

    return n
```

