def newman_prime(n):
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        i = 3
        while i * i <= num:
            if num % i == 0:
                return False
            i += 2
        return True

    def generate_nsw():
        a, b = 1, 1
        while True:
            yield a
            a, b = b, 2 * b + a

    count = 0
    for num in generate_nsw():
        if is_prime(num):
            count += 1
            if count == n:
                return num
